#!/usr/bin/env python3
"""Describe shipped SVGs and WAVs without changing resources or game data."""
from pathlib import Path
import json,re,wave
ROOT=Path(__file__).resolve().parents[1]
b=json.loads((ROOT/'data/balance.json').read_text())
uses={'fallback':'Missing-art safety fallback','clinic_bg':'Clinic, recalibration and ending backdrop','sandtray':'Clinic/recalibration/ending tray','sand_layer':'Brush-mask sand surface','clinic_figure':'Talk-sample figure','buried_runner_doll':'Clinic reveal, trance focus, ending','mina_idle':'Stationary Mina','mina_walk':'Mina below walk cutoff','mina_jog':'Mina below jog cutoff','mina_run':'Mina at running pace','mina_crouch':'Automatic hiding behind covers','mina_caught':'1.2 s capture animation','run_bg_far':'Parallax ×0.2','run_bg_mid':'Parallax ×0.5','run_bg_near':'Parallax ×0.8, butterflies','run_ground':'Tiled ground','flower_bud':'Syllable bloom start','flower_open':'Decorative and sung flowers','flower_bridge':'88–100 m lifting bridge','tex_grain':'PostFX grain','tex_paper':'PostFX paper','tex_hatch':'Dual derivation','ui_voice_meter':'520×70 voice meter backing','ui_voice_marker':'Replaceable marker asset; ticks drawn by HUD','ui_lyrics_bar':'1400×130 lyrics backing','ui_subtitle':'Therapist/ME backing','ui_panel':'Settings panel','ui_panel_wide':'End screen backing','ui_beat_ring':'S5 downbeat call around Mina','cover_flower_big':'600/680 m automatic hiding','cover_desk':'860 m hiding; smaller seeded decoration','cover_locker':'1000 m hiding','cover_bag':'Available cover key; no placement in the specified level','gap_crack':'Five speed gates, 2 m logical width','prop_school_item':'Seeded S2–S4 decoration','safe_puddle':'Eight checkpoint/safe zones; clinic-window reflection','light_door':'1140 m finale exit','m1_wall':'Chaser wall of overlapping faces; animated gaze ahead','m1_face_peek':'Left edge presence at 9.5–16 m','m2_sky_crack':'Warning/Gaze/Recede sky opening','m2_eye_open':'Gaze and finale eye','m2_eye_closed':'Recede and finale eye closure','m2_beam':'Additive swept sight exposure','m2_hand':'First hearing-warning slam'}
rows=[]
for path in sorted((ROOT/'art').glob('*.svg')):
    if path.name.startswith('r1_override_probe'):continue
    m=re.search(r'width="(\d+)" height="(\d+)"',path.read_text());w,h=map(int,m.groups());key=path.stem;base=key.removesuffix('_cute').removesuffix('_real');n=b['art_frames'].get(base,1)
    dual='yes' if base!=key else ('real only' if key.startswith(('m1_','m2_')) else 'no')
    rows.append(f'| `{key}` | {w}×{h} ({w//n}×{h}/frame) | {dual} | {n} | {uses.get(base,"Shipped resource")} |')
text='# R1/R2 art manifest\n\nAll textures route through ArtRegistry. Fixed slots center and preserve aspect at replacement resolutions; PNG overrides SVG. Dual and animated keys use their base `art_frames` count. R3-only assets (face closeup, flow petals and music layers) remain absent.\n\n| Key | SVG source size | Dual | Frames | Purpose / usage |\n| --- | --- | --- | --- | --- |\n'+'\n'.join(rows)+'\n\nGenerated by `tools/generate_resources.py`; no text is baked into textures. Backgrounds, ground, hatch/grain/paper tile. `tools/write_manifest.py` refreshes this document without changing game data or resources.\n\n## Audio\n\nOriginal synthesis, replaceable by same-name WAV then OGG. Ambience/music loop; effects are one-shot.\n\n| Key | WAV duration | Loop |\n| --- | --- | --- |\n'
for path in sorted((ROOT/'audio').glob('*.wav')):
    with wave.open(str(path)) as source: duration=source.getnframes()/source.getframerate()
    text+=f'| `{path.stem}` | {duration:.2f} s | {"yes" if path.stem.startswith(("amb_","mus_")) else "no"} |\n'
(ROOT/'ART_MANIFEST.md').write_text(text)
